INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `Flags`, `RewardItem1`, `RewardAmount1`, `RewardFactionID1`, `RewardFactionOverride1`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `RequiredItemId1`, `RequiredItemCount1`) VALUES
(9503701, 2, -1, 35, -101, 4096, 9503700, 1, 1170, 50000, 'Mudfish Mayhem', 'Bring 6 Marsh Mudfish to Nat Pagle. Fish for them in the waters of Dustwallow Marsh.', 'The mudfish around this isle have gotten bold. Bold and tasty.$b$bCast anywhere in the waters of Dustwallow Marsh and bring me six Marsh Mudfish. I\'d do it myself, but I\'m busy. Resting your eyes is a kind of fishing too, $N.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503701, 6),
(9503702, 2, -1, 35, -101, 4096, 9503700, 1, 1170, 50000, 'Fin Soup', 'Bring 4 Reef Shark Fins to Nat Pagle. Fish for them in the waters of Stranglethorn Vale.', 'Booty Bay pays good coin for shark fin soup, and I pay good coin for not having to row to Stranglethorn.$b$bFish the coast of Stranglethorn Vale and bring me four Reef Shark Fins. The sharks bite through the line more often than not, so the fin is usually all you get. Suits me.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503702, 4),
(9503703, 2, -1, 35, -101, 4096, 9503700, 1, 1170, 50000, 'Sorriest Bait in the World', 'Bring 5 Sorrowmoss Eels to Nat Pagle. Fish for them in the waters of Swamp of Sorrows.', 'The eels in the Swamp of Sorrows are the sorriest-looking things you\'ve ever seen, and the best bait there is for a Dustwallow snapper.$b$bBring me five Sorrowmoss Eels from the swamp\'s waters. Keep them wet. They sulk when they dry out.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503703, 5),
(9503704, 2, -1, 35, -101, 4096, 9503700, 1, 1170, 50000, 'Glimmerfin by Moonlight', 'Bring 5 Feathermoon Glimmerfins to Nat Pagle. Fish for them in the waters of Feralas.', 'There\'s a fish in Feralas that shines like a lantern under the moon. The night elves at Feathermoon call it glimmerfin.$b$bFish the rivers and the coast of Feralas and bring me five. I want to see if they glow in a bucket too.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503704, 5),
(9503705, 2, -1, 35, -101, 4096, 9503700, 1, 1170, 50000, 'The Goblin\'s Bet', 'Bring Steamwheedle Swordfish to Nat Pagle. Fish for it in the waters of Tanaris.', 'A goblin in Gadgetzan swears he hooked a swordfish off the Tanaris coast as long as his boat. I bet him ten gold he\'s lying.$b$bProve me wrong. Fish the waters of Tanaris and bring me a Steamwheedle Swordfish. If I\'m going to lose the bet, I want to see the fish.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503705, 1),
(9503706, 2, -1, 35, -101, 4096, 9503700, 1, 1170, 50000, 'Highborne Trinkets', 'Bring 3 Tarnished Highborne Trinkets to Nat Pagle. Fish for them in the waters of Azshara.', 'The bays of Azshara are full of what the Highborne dropped when their city went under: rings, bangles, little silver fish charms. Anglers hook them all the time.$b$bBring me three. None of them are worth anything, but I like collecting them.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503706, 3),
(9503707, 2, -1, 58, -101, 4096, 34863, 1, 1170, 50000, 'Sporefish Surprise', 'Bring 6 Glowing Sporefish to Nat Pagle. Fish for them in the waters of Zangarmarsh.', 'Over in Outland there\'s a marsh full of giant mushrooms, and the fish there eat the spores.$b$bFish the waters of Zangarmarsh and bring me six Glowing Sporefish. The Sporeggar say they\'re good eating. The Sporeggar also eat dirt, so I\'d like to judge for myself.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503707, 6),
(9503708, 2, -1, 58, -101, 4096, 34863, 1, 1170, 50000, 'Fel-Scorched Crawdads', 'Bring 5 Fel-Scorched Crawdads to Nat Pagle. Fish for them in the waters of Hellfire Peninsula.', 'Nothing should live in the water on Hellfire Peninsula. The crawdads didn\'t get the message.$b$bBring me five Fel-Scorched Crawdads from Hellfire\'s pools. Use gloves.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503708, 5),
(9503709, 2, -1, 58, -101, 4096, 34863, 1, 1170, 50000, 'The Crystalfin', 'Bring Oshu\'gun Crystalfin to Nat Pagle. Fish for it in the waters of Nagrand.', 'The Kurenai say a fish lives in the lakes of Nagrand whose scales are as clear as the crystals of Oshu\'gun.$b$bOne would do. Fish the lakes of Nagrand and bring me an Oshu\'gun Crystalfin.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503709, 1),
(9503710, 2, -1, 58, -101, 4096, 34863, 1, 1170, 50000, 'Spirit-Touched Bluefish', 'Bring 5 Spirit-Touched Bluefish to Nat Pagle. Fish for them in the waters of Terokkar Forest.', 'My old friend Barlo fishes the lakes of Terokkar and won\'t stop talking about the bluefish there. Something about the spirits in the water.$b$bBring me five Spirit-Touched Bluefish from Terokkar Forest. I\'d like to know what he\'s on about.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503710, 5),
(9503711, 2, -1, 68, -101, 4096, 46007, 1, 1170, 50000, 'Borean Ice Cod', 'Bring 6 Borean Ice Cod to Nat Pagle. Fish for them in the waters of Borean Tundra.', 'Cod from the Borean Tundra keeps for a month without salt. It\'s frozen before it leaves the water.$b$bBring me six Borean Ice Cod from the tundra\'s waters. I\'m stocking up for the winter, whenever that is in Dustwallow.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503711, 6),
(9503712, 2, -1, 68, -101, 4096, 46007, 1, 1170, 50000, 'Hookjaws of the Fjord', 'Bring 5 Fjord Hookjaws to Nat Pagle. Fish for them in the waters of Howling Fjord.', 'The vrykul in the Howling Fjord fish for hookjaws with spears. I fish for them with a chair and a nap. You\'ll do it with a pole.$b$bBring me five Fjord Hookjaws from the Howling Fjord.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503712, 5),
(9503713, 2, -1, 68, -101, 4096, 46007, 1, 1170, 50000, 'Rainbow Trout', 'Bring 5 Grizzly Hills Rainbow Trout to Nat Pagle. Fish for them in the waters of Grizzly Hills.', 'The rivers of the Grizzly Hills run so clear you can watch the trout ignore your bait.$b$bBring me five Grizzly Hills Rainbow Trout. Watch out for the bears. They fish too, and they don\'t like to share.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503713, 5),
(9503714, 2, -1, 68, -101, 4096, 46007, 1, 1170, 50000, 'The Wyrmrest Snapper', 'Bring Wyrmrest Snapper to Nat Pagle. Fish for it in the waters of Dragonblight.', 'The dragons of Wyrmrest Temple have a taste for one fish, and they don\'t share it.$b$bFish the waters of Dragonblight and bring me a Wyrmrest Snapper before they eat them all.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503714, 1),
(9503715, 2, -1, 68, -101, 4096, 46007, 1, 1170, 50000, 'Sholazar Glimmerscale', 'Bring 5 Sholazar Glimmerscales to Nat Pagle. Fish for them in the waters of Sholazar Basin.', 'The Sholazar Basin is warm in the middle of Northrend, and the fish there have colours nobody has names for.$b$bBring me five Sholazar Glimmerscales. I want to paint one.', 'Return to Nat Pagle in Dustwallow Marsh.', 9503715, 5);
