INSERT INTO `quest_request_items` (`ID`, `CompletionText`) VALUES
(9503701, 'Back already? Let\'s see the haul.'),
(9503702, 'Smells like Booty Bay. Did you get them?'),
(9503703, 'Are they still wriggling?'),
(9503704, 'Did you find the glowing ones?'),
(9503705, 'Well? Is the goblin a liar or not?'),
(9503706, 'Got anything shiny for me?'),
(9503707, 'Do they still glow?'),
(9503708, 'Did you use gloves?'),
(9503709, 'Any luck in Nagrand?'),
(9503710, 'Did Barlo see you? Don\'t tell him they\'re for me.'),
(9503711, 'Still frozen?'),
(9503712, 'The vrykul didn\'t give you trouble, I hope.'),
(9503713, 'Any trouble with the bears?'),
(9503714, 'Did a dragon follow you here?'),
(9503715, 'Did you bring my colours?');
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`) VALUES
(9503701, 'Now those are mudfish. Here, take this. Some old tackle I don\'t use.'),
(9503702, 'Four fins, and you\'ve still got all your fingers. Good work.'),
(9503703, 'Look at those faces. A snapper won\'t be able to resist.'),
(9503704, 'They do glow! Well, a little. Don\'t tell anyone I got excited.'),
(9503705, 'Huh. Not as long as a boat, but long enough. I owe a goblin ten gold. Take this before I change my mind.'),
(9503706, 'Oh, this one has a fish on it. I\'m keeping that one.'),
(9503707, 'Smells like a cave. Tastes... also like a cave. Thanks anyway.'),
(9503708, 'They\'re warm. Why are they warm? Never mind. Here\'s your pay.'),
(9503709, 'You can see right through it. That\'s the finest fish I\'ve seen in years.'),
(9503710, 'They\'re... ordinary bluefish. Barlo\'s been out in the sun too long.'),
(9503711, 'Cold as a lich\'s heart. Perfect.'),
(9503712, 'Look at those jaws. No wonder the vrykul use spears.'),
(9503713, 'Every colour of the rainbow. Some of them twice.'),
(9503714, 'If a dragon comes looking for this, you never saw me.'),
(9503715, 'Beautiful. I\'ll never be able to paint that. Here, you earned this.');
